import numpy as np
def Rz(a):
    c,s=np.cos(a),np.sin(a); M=np.eye(4); M[0,0]=c;M[0,1]=-s;M[1,0]=s;M[1,1]=c; return M
def Ry(a):
    c,s=np.cos(a),np.sin(a); M=np.eye(4); M[0,0]=c;M[0,2]=s;M[2,0]=-s;M[2,2]=c; return M
def T(x,y,z):
    M=np.eye(4); M[:3,3]=[x,y,z]; return M
def fk(q, upto=None):
    q1,q2,q3,q4,q5,q6,q7=q
    frames={}
    M=Rz(q1)@T(0,0,0.2); frames['shoulder']=M.copy()
    M=M@Ry(q2)@Rz(q3)@T(0,0,0.3); frames['elbow']=M.copy()
    M=M@Ry(q4)@Rz(q5)@T(0,0,0.3); frames['wrist']=M.copy()
    M=M@Ry(q6)@Rz(q7)@T(0,0,0.1); frames['hand']=M.copy()
    return frames if upto else M
F=415.692  # 240/tan(30deg)
def pix_ray(H,u,v,cam_off=0.011):
    # u right, v down pixel coordinates; returns origin, dir in cell frame
    x=(u-240)/F; y=(v-240)/F   # image right=+x hand; image up=-y hand -> down=+y
    d=H[:3,:3]@np.array([x,y,1.0]); o=(H@np.array([0,0,cam_off,1]))[:3]
    return o,d/np.linalg.norm(d)
def to_plane(H,u,v,z):
    o,d=pix_ray(H,u,v); t=(z-o[2])/d[2]; return o+t*d
def project(H,p,cam_off=0.011):
    Hi=np.linalg.inv(H); pc=(Hi@np.append(p,1))[:3]; pc[2]-=cam_off
    return 240+F*pc[0]/pc[2], 240+F*pc[1]/pc[2], pc[2]
