from seg import *; from kin import *
import numpy as np
def centerline(f, vmin=0, vmax=480):
    lab=classify(load(f)); pts=[]
    for v in range(vmin,vmax,5):
        rr=[r for r in runs(lab[v]==1) if r[1]-r[0]>=1]
        if rr: pts.append(((rr[0][0]+rr[-1][1])/2, v, rr[-1][1]-rr[0][0]))
    return np.array(pts)
def plane(q,pts):
    H=fk(q); ds=[pix_ray(H,u,v)[1] for u,v,_ in pts]; o=pix_ray(H,240,240)[0]
    # fit plane through o containing directions: smallest singular vector
    D=np.array(ds); _,_,vt=np.linalg.svd(D); n=vt[-1]; return n, o
def inter(p1,p2):
    n1,o1=p1;n2,o2=p2; d=np.cross(n1,n2); d/=np.linalg.norm(d)
    A=np.array([n1,n2,d]); b=np.array([n1@o1,n2@o2,0]); p=np.linalg.solve(A,b); return p,d
Q={'v1':[0,0,0,1.14,0,2.0,0],'v2':[0,0,0,0.5,0,2.0,0],'v3':[-0.7,0,0,0.6,0,2.0,0],'park':[0,0,0,1.5708,0,1.5708,0]}
