import numpy as np
from kin import *
BOXES={'track':([0.33,-0.52,0.0],[0.47,0.30,0.20]),'hopper':([0.33,-0.66,0.0],[0.52,-0.44,0.30]),
       'bin':([0.32,0.27,0.0],[0.52,0.47,0.12]),'basket':([0.12,0.27,0.0],[0.31,0.46,0.08]),'table':([-2,-2,-1],[2,2,0.0])}
def arm_pts(q,gap=0.06):
    f=fk(q,upto=True); pts=[]
    sh=f['shoulder'][:3,3]; el=f['elbow'][:3,3]; wr=f['wrist'][:3,3]; H=f['hand']
    for a,b,r in [(sh,el,0.04),(el,wr,0.033)]:
        for t in np.linspace(0,1,8): pts.append((a+t*(b-a),r))
    for lx in (-0.03,0.03):
        for ly in (-0.02,0.02):
            for lz in (-0.01,0.01): pts.append(((H@[lx,ly,lz,1])[:3],0.0))
    for s in (-1,1):
        for lz in (0.01,0.04,0.07):
            for ly in (-0.012,0.012): pts.append(((H@[s*(gap/2+0.004),ly,lz,1])[:3],0.004))
    return pts
def clearance(q,boxes=BOXES,skip=()):
    best=(9,None)
    for name,(lo,hi) in boxes.items():
        if name in skip: continue
        lo=np.array(lo);hi=np.array(hi)
        for p,r in arm_pts(q):
            d=np.linalg.norm(np.maximum(0,np.maximum(lo-p,p-hi)))-r
            if d<best[0]: best=(d,name)
    return best
def path_clear(qa,qb,n=40,**kw):
    qa=np.array(qa);qb=np.array(qb)
    return min((clearance(qa+t*(qb-qa),**kw)+(t,) for t in np.linspace(0,1,n)),key=lambda x:x[0])
