from line3d import *
Q['v4']=[0.9,0,0,0.6,0,2.0,0]; Q['v5']=[-0.283,0.129,-0.291,1.46,-0.545,0.907,-0.202]
import numpy as np
def obs_pts(k,vmin,vmax,umin=0,umax=480):
    lab=classify(load('/app/output/%s.png'%k)); out=[]
    for v in range(vmin,vmax,4):
        rr=[r for r in runs(lab[v,umin:umax]==1) if r[1]-r[0]>=1]
        if rr: out.append(((rr[0][0]+rr[-1][1])/2+umin,v))
    return np.array(out)
def resid(par,data):
    x0,z0,dx,dz=par; res=[]
    for k,pts in data:
        H=fk(Q[k])
        # project line samples, compute distance from each obs point to projected polyline
        ys=np.linspace(-0.6,0.4,201); P=np.array([project(H,np.array([x0+dx*y,y,z0+dz*y])) for y in ys])
        P=P[P[:,2]>0.02]
        for u,v in pts:
            d=np.min(np.hypot(P[:,0]-u,P[:,1]-v)); res.append(d)
    return np.array(res)
def fit(data,par=(0.4,0.16,0.0,-0.05)):
    par=np.array(par,float)
    for it in range(30):
        r=resid(par,data); J=np.zeros((len(r),4))
        for i in range(4):
            dp=np.zeros(4); dp[i]=1e-4; J[:,i]=(resid(par+dp,data)-r)/1e-4
        step=np.linalg.lstsq(J,-r,rcond=None)[0]; par+=step
        if np.linalg.norm(step)<1e-6: break
    return par, np.sqrt(np.mean(resid(par,data)**2))
