from seg import *; from kin import *
import numpy as np
QA=[0.0,0.451,0.0,1.317,0.0,1.373,0.0]; QB=[0.0,0.489,0.0,0.756,0.0,1.897,0.0]
def edges(k,vs):
    im=load('/app/output/%s.png'%k); r,g,b=im[...,0],im[...,1],im[...,2]
    blue=(b-r>40); light=(b-r>70)&(g>140); out=[]
    for v in vs:
        rr=[x for x in runs(blue[v,100:400]) if x[1]-x[0]>3]; ll=[x for x in runs(light[v,100:400]) if x[1]-x[0]>3]
        if rr and ll: out.append((v,rr[0][0]+100-0.5,rr[-1][1]+100+0.5,ll[0][0]+100-0.5,ll[-1][1]+100+0.5))
