import sys, json, subprocess, numpy as np
from seg import load
from kin import *
def sh(cmd): return subprocess.run(cmd,shell=True,capture_output=True,text=True).stdout
def state(): return json.loads(sh('robot state'))
def odd_mask(im):
    r,g,b=im[...,0],im[...,1],im[...,2]
    mx=im.max(-1); mn=im.min(-1); sat=mx-mn
    grey=sat<35
    blueish=(b>r+25)&(b>=g-5)   # track blues, navy
    return (~grey)&(~blueish)
def blobs(mask,minpix=30):
    # simple connected components (4-neigh) via flood fill on downsampled grid
    H,W=mask.shape; lab=np.zeros((H,W),int); out=[]; n=0
    ys,xs=np.nonzero(mask)
    for y0,x0 in zip(ys,xs):
        if lab[y0,x0]: continue
        n+=1; st=[(y0,x0)]; lab[y0,x0]=n; pts=[]
        while st:
            y,x=st.pop(); pts.append((y,x))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                yy,xx=y+dy,x+dx
                if 0<=yy<H and 0<=xx<W and mask[yy,xx] and not lab[yy,xx]:
                    lab[yy,xx]=n; st.append((yy,xx))
        if len(pts)>=minpix:
            p=np.array(pts); out.append(dict(n=len(pts),v=p[:,0].mean(),u=p[:,1].mean(),vmin=p[:,0].min(),vmax=p[:,0].max(),umin=p[:,1].min(),umax=p[:,1].max()))
    return out
if __name__=='__main__':
    f=sys.argv[1]; im=load(f); m=odd_mask(im)
    for b in blobs(m): 
        b['rgb']=im[int(b['v']),int(b['u'])].astype(int).tolist(); print(b)
