def ik_fixed(p,zdir,xdir,q0,fix_i,fix_v,iters=60):
    q=np.array(q0,float); q[fix_i]=fix_v
    free=[i for i in range(7) if i!=fix_i]
    for it in range(iters):
        e=pose_err(q,p,zdir,xdir); J=np.zeros((len(e),6))
        for k,i in enumerate(free):
            dq=np.zeros(7); dq[i]=1e-6; J[:,k]=(pose_err(q+dq,p,zdir,xdir)-e)/1e-6
        st=np.linalg.lstsq(J,-e,rcond=None)[0]
        for k,i in enumerate(free): q[i]+=st[k]
        if np.linalg.norm(st)<1e-10: break
    return q,np.linalg.norm(pose_err(q,p,zdir,xdir))
def best_G(y,ref,clear=0.004):
    palm=np.array([track_x(y),y,track_top(y)+clear+0.07]); z=np.array([0,0,-1.]); x=np.array([-1.,0,0])
    G0,_=ambush(y,clear=clear,q0=ref); best=(np.abs(G0-ref).max(),G0)
    for fi in (2,4):
        for fv in np.linspace(ref[fi]-0.4,ref[fi]+0.4,41):
            q,e=ik_fixed(palm,z,x,G0,fi,fv)
            if e<1e-6 and np.all(np.abs(q)<=LIM):
                m=np.abs(q-ref).max()
                if m<best[0]: best=(m,q)
    return best
