from loc import *
from seg import load, runs
def outer_edges(f,vs):
    im=load(f); r,g,b=im[...,0],im[...,1],im[...,2]; blue=(b-r>40); out=[]
    for v in vs:
        rr=[x for x in runs(blue[v,55:470]) if x[1]-x[0]>3]
        if rr: out.append((v,rr[0][0]+55-0.5,rr[-1][1]+55+0.5))
    return out
def model_edges(q,v,dz=0,dx=0,ds=0,W=0.0587):
    H=fk(q); res=[]
    for s in (-1,1):
        ys=np.linspace(-0.2,0.35,551)
        P=np.array([project(H,np.array([0.433+dx+s*W/2,y,0.0833-(0.0875+ds)*y+dz])) for y in ys])
        i=np.argsort(P[:,1]); res.append(np.interp(v,P[i,1],P[i,0]))
    return res
def fit_track(f,q,vs):
    E=outer_edges(f,vs); p=np.zeros(3)
    def R(p):
        r=[]
        for v,l,rr in E:
            ml,mr=model_edges(q,v,*p); r+= [ml-l, mr-rr]
        return np.array(r)
    for it in range(8):
        r=R(p); J=np.zeros((len(r),3))
        for i in range(3):
            dp=np.zeros(3); dp[i]=1e-4; J[:,i]=(R(p+dp)-r)/1e-4
        p+=np.linalg.lstsq(J,-r,rcond=None)[0]
    return p, R(p), E
